<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/finance_step16.php';if(empty($_SESSION['fa_csrf']))$_SESSION['fa_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['fa_csrf'];$error=null;$success=null;$accounts=[];$cats=[];
try{$pdo=business_db();finance_step16_ensure($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'');if($action==='account'){$id=finance_step16_create_cash_account($pdo,$_POST);$success='Cash/Bank account #'.$id.' created.';}elseif($action==='category'){$id=finance_step16_create_ledger_category($pdo,(string)($_POST['category_name']??''),(string)($_POST['category_class']??''));$success='Finance category #'.$id.' created.';}}$accounts=finance_step16_accounts($pdo,$orgId);$stmt=$pdo->prepare("SELECT * FROM finance_ledger_accounts WHERE organization_id=? AND account_class IN ('income','expense') AND status='active' ORDER BY account_class,account_code");$stmt->execute([$orgId]);$cats=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function fa_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fa_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
