t type="hidden" name="action" value="account"><label>Account Name<input name="account_name" placeholder="e.g. Main Cash / SBI Business" required></label><label>Type<select name="account_type"><option value="cash">Cash</option><option value="bank">Bank</option><option value="upi">UPI</option><option value="wallet">Wallet</option><option value="other">Other</option></select></label><label>Institution Name<input name="institution_name" placeholder="Optional"></label><label>Account Last 4 Digits<input name="account_last4" maxlength="8" placeholder="Optional"></label><label>Opening Balance<input type="number" step="0.01" name="opening_balance" value="0"></label><label>Opening Balance Date<input type="date" name="opening_date" value="<?= date('Y-m-d') ?>"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><button>Create Account →</button></form></article><article class="os-card pp-span-6"><h2>Create Income / Expense Category</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= fa_h($csrf) ?>"><input type="hidden" name="action" value="category"><label>Category Name<input name="category_name" placeholder="e.g. Club Rent / Consultation Income" required></label><label>Classification<select name="category_class"><option value="expense">Expense</option><option value="income">Income</option></select></label><button>Create Category →</button></form><h2 style="margin-top:18px">Available Categories</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Code</th><th>Name</th><th>Class</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?= fa_h($c['account_code']) ?></td><td><b><?= fa_h($c['account_name']) ?></b><?= $c['is_system']?'<small>System</small>':'<small>Custom</small>' ?></td><td><?= fa_h(strtoupper($c['account_class'])) ?></td></tr><?php endforeach;?></tbody></table></div></article></section><section class="os-card" style="margin-top:14px"><h2>Cash / Bank & Clearing Accounts</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Account</th><th>Type</th><th>Institution</th><th>Last 4</th><th>Opening</th><th>Current</th><th>State</th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><b><?= fa_h($a['account_name']) ?></b><small><?= fa_h($a['account_code']) ?></small></td><td><?= fa_h(strtoupper($a['account_type'])) ?></td><td><?= fa_h($a['institution_name']?:'—') ?></td><td><?= fa_h($a['account_last4']?:'—') ?></td><td><?= fa_m($a['opening_balance']) ?></td><td><b><?= fa_m($a['current_balance']) ?></b></td><td><span class="pp-badge <?= $a['is_system_clearing']?'warn':'' ?>"><?= $a['is_system_clearing']?'SYSTEM CLEARING':'USER ACCOUNT' ?></span></td></tr><?php endforeach;?></tbody></table></div></section><div class="os-footer-note"><strong>Privacy rule:</strong> STEP 16 does not need full bank account numbers or credentials. Last-4 is optional display metadata only.</div><?php endif;?></main></div></body></html>